import datetime,json,os,platform,traceback
from pathlib import Path
from pyroute2 import IPRoute,Ethtool
out={"utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"interface":"eth0","netns":os.readlink("/proc/self/ns/net"),"kernel":platform.release(),"mtu":int(Path("/sys/class/net/eth0/mtu").read_text()),"read_only":True}
with IPRoute() as ipr:
 link=ipr.get_links(ipr.link_lookup(ifname="eth0")[0])[0]
 out["limits"]={k:link.get_attr(k) for k in ["IFLA_MTU","IFLA_GSO_MAX_SEGS","IFLA_GSO_MAX_SIZE","IFLA_GRO_MAX_SIZE","IFLA_TSO_MAX_SIZE","IFLA_TSO_MAX_SEGS"]}
try:
 tool=Ethtool()
 fs=tool.get_features("eth0").features
 out["features"]={name:{"enabled":bool(f.enable),"available":bool(f.available)} for name,f in fs.items()}
 tool.close()
except Exception:
 out["features_error"]=traceback.format_exc()
print(json.dumps(out,sort_keys=True))
